<section class="container section narrow"><p class="eyebrow">ACCESO PERSONAL</p><h1>Mi cuenta</h1><p><?= e(\App\Services\Security::user()['correo']) ?></p><?php if(\App\Services\Security::user()['debe_cambiar_password']): ?><p class="notice">Antes de continuar, reemplaza tu contraseña temporal.</p><?php endif; ?><?php require ROOT.'/app/Views/errors.php'; ?><form class="form-panel" method="post" action="<?= e(url('cuenta')) ?>" data-submit><?= csrf() ?><label for="actual">Contraseña actual</label><input id="actual" type="password" name="actual" autocomplete="current-password" required><label for="password">Nueva contraseña (mínimo 12 caracteres)</label><input id="password" type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required><label for="password_confirmation">Repite la nueva contraseña</label><input id="password_confirmation" type="password" name="password_confirmation" minlength="12" maxlength="72" autocomplete="new-password" required><button class="button" type="submit">Cambiar contraseña</button></form></section>
